// Scenarios: each one a real operating situation, told without and with
// AetherSDR. WITHOUT lists the separate programs the workflow needs (they
// become the floating windows) and the links between them (the cables:
// audio, cat, net, ptt, usb). WITH keeps any program AetherSDR does not
// replace — loggers and decoders stay — and counts what is left honestly.
// Unsourced workflow lines are marked "(common practice)".

const T = (name, role, os, kind = 'list') => ({ name, role, os, kind, accent: os === 'Windows' ? '#f0a35e' : os === 'browser' ? '#86efac' : os === 'hardware' ? '#fde68a' : '#93c5fd' });

